content.text:
Every scenario fits the existing surface, so `h.d.ts`, `kernel.d.ts` and `design.md` are unchanged and only the five scenario files follow. One deviation: the battery imports scenario 7's shared entities from a common module, but scenario files may import only from the library. So `07-multi-tenant.ts` defines the shared entities at the top of the file and builds both harnesses from them. Nothing here has been run through the compiler.

=== FILE: scenarios/06-content-taste.ts ===
import { z } from 'zod';
import { H } from 'harness-dsl';
import type { PolicyContext } from 'harness-dsl/kernel';
import * as claude from 'harness-dsl/claude-code';
import * as wordpress from 'harness-dsl/wordpress';
import * as sqlite from 'harness-dsl/sqlite';
import * as jsonl from 'harness-dsl/jsonl';
import * as local from 'harness-dsl/local';
import * as markdown from 'harness-dsl/markdown';

const Queued = H.state('Queued', 'pending');
const Reviewing = H.state('Reviewing', 'active');
const Accepted = H.state('Accepted', 'terminal', 'success');
const Returned = H.state('Returned', 'terminal', 'failure');
const ReviewBroken = H.state('ReviewBroken', 'terminal', 'failure');

const Draft = H.work('Draft')
  .attributes({ postId: z.number(), section: z.string(), title: z.string() })
  .fields({ content: z.string() })
  .states([Queued, Reviewing, Accepted, Returned, ReviewBroken])
  .key((unit) => String(unit.attributes.postId));

const connection = { site: 'https://magazine.example.com', token: H.env('WORDPRESS_TOKEN') };

const subscription = claude.subscription('editorial-max', { configDir: H.env('CLAUDE_CONFIG_DIR') });
const opus = claude.model('claude-opus-4');
const sonnet = claude.model('claude-sonnet-4');
const challenger = claude.model('claude-haiku-4');

const ranked = H.policy.recall('specific-then-proven', (c) =>
  [...c.candidates]
    .sort((a, b) => b.specificity - a.specificity || b.track.succeeded - a.track.succeeded)
    .slice(0, c.limit),
);

const editorialTaste = H.memory.taste('editorial-taste').curated();
const factChecking = H.memory.experience('fact-checking');

const tasteJournal = H.journal('editor-taste', editorialTaste)
  .store(jsonl.memory('memory/taste.jsonl'))
  .recall(ranked);
const factJournal = H.journal('fact-lessons', factChecking)
  .store(jsonl.memory('memory/fact-checking.jsonl'))
  .recall(ranked);

const window = { days: 30 };

function weakerReviewer(c: PolicyContext): 'a' | 'b' | null {
  const a = c.metrics.read(actedOnA, { lane: drafts, window });
  const b = c.metrics.read(actedOnB, { lane: drafts, window });
  if (a.n < 50 || b.n < 50 || a.rate === null || b.rate === null) return null;
  if (a.rate < b.rate) return 'a';
  if (b.rate < a.rate) return 'b';
  return null;
}

const reviewerAModel = H.policy.model('reviewer-a-model', [opus, challenger], (c) =>
  weakerReviewer(c) === 'a' ? challenger : opus,
);
const reviewerBModel = H.policy.model('reviewer-b-model', [sonnet, challenger], (c) =>
  weakerReviewer(c) === 'b' ? challenger : sonnet,
);

const reviewer = H.role('reviewer')
  .intents(['read', 'remember'])
  .instructions('Critique the draft for argument, accuracy and house style. Name concrete passages.')
  .input({ title: z.string(), section: z.string(), content: z.string() })
  .output({ critique: z.string(), issues: z.array(z.string()) });

const reviewerA = H.agent('reviewer-a', reviewer)
  .model(reviewerAModel)
  .pool(subscription)
  .recalls([tasteJournal, factJournal]);
const reviewerB = H.agent('reviewer-b', reviewer)
  .model(reviewerBModel)
  .pool(subscription)
  .recalls([tasteJournal, factJournal]);

const mergeCritiques = H.command('merge-critiques', ['node', 'scripts/merge-critiques.js']).parses({
  merged: z.string(),
});
const factCheck = H.command('fact-check', ['node', 'scripts/fact-check.js']).parses({
  repeatMistake: z.boolean(),
  lesson: z.string(),
  because: z.string(),
});

const reviewFlow = H.flow('draft-review')
  .requires({ title: z.string(), section: z.string(), content: z.string() })
  .mark('reviewing')
  .step('critiqueA', reviewerA, (c) => ({ title: c.input.title, section: c.input.section, content: c.input.content }))
  .step('critiqueB', reviewerB, (c) => ({ title: c.input.title, section: c.input.section, content: c.input.content }))
  .step('merge', mergeCritiques, (c) => ({
    stdin: JSON.stringify({ a: c.out.critiqueA, b: c.out.critiqueB }),
  }), { onRestart: 'rerun' })
  .step('factCheck', factCheck, (c) => ({ stdin: c.input.content }), { onRestart: 'rerun' })
  .halt('editor', {
    ask: (c) => `Review "${c.input.title}" (${c.input.section}).\n\n${c.out.merge.data.merged}`,
    decision: {
      verdict: z.enum(['accept', 'return']),
      notes: z.string(),
      actedOn: z.enum(['a', 'b', 'both', 'neither']),
    },
  })
  .ends(['accepted', 'returned'], (c) => (c.out.editor.verdict === 'accept' ? 'accepted' : 'returned'));

const actedOnA = H.metric('editor-acted-on-a')
  .step(reviewFlow, 'editor')
  .hit((decision) => decision.actedOn === 'a' || decision.actedOn === 'both');
const actedOnB = H.metric('editor-acted-on-b')
  .step(reviewFlow, 'editor')
  .hit((decision) => decision.actedOn === 'b' || decision.actedOn === 'both');

const drafts = H.lane('drafts', Draft)
  .supply([
    wordpress.poll(Draft, H.time.every({ minutes: 10 }), { ...connection, status: 'pending' }, (post) => ({
      attributes: { postId: post.id, section: post.section, title: post.title },
      fields: { content: post.content },
    })),
  ])
  .store(wordpress.store(Draft, {
    ...connection,
    status: { Reviewing: 'pending', Accepted: 'publish', Returned: 'draft', ReviewBroken: 'pending' },
  }))
  .handler(reviewFlow, {
    states: { reviewing: Reviewing, accepted: Accepted, returned: Returned, failed: ReviewBroken },
  })
  .runner(local.shell({ slots: 2 }))
  .wip(4);

const returnedNotesBecomeTaste = H.trigger('returned-notes-to-taste', H.on.transition(drafts, { to: [Returned] }))
  .where((e) => (e.outputs.editor?.notes ?? '').trim().length > 0)
  .records(tasteJournal, (e) => [
    {
      rule: e.outputs.editor?.notes ?? '',
      because: `the editor returned "${e.unit.attributes.title}" with this note`,
      when: { kinds: [Draft], attributes: { section: e.unit.attributes.section } },
    },
  ]);

const repeatMistakesBecomeExperience = H.trigger('repeat-mistake-to-experience', H.on.step(drafts, 'factCheck'))
  .where((e) => e.output.data.repeatMistake)
  .records(factJournal, (e) => [
    { rule: e.output.data.lesson, because: e.output.data.because, when: { kinds: [Draft] } },
  ]);

const editorAccess = H.access('editor').allows([
  H.ops.readWork,
  H.ops.resolveBlocks,
  H.ops.readMemory,
  H.ops.writeMemory,
  H.ops.curateMemory,
  H.ops.readTelemetry,
]);

export const contentHarness = H.harness('content-review')
  .ledger(sqlite.ledger('content-ledger.sqlite'))
  .lanes([drafts])
  .triggers([returnedNotesBecomeTaste, repeatMistakesBecomeExperience])
  .schedule(H.policy.schedule('oldest-first', (c) => ({
    start: [...c.candidates].sort((a, b) => b.waitedMs - a.waitedMs),
  })))
  .clients([claude.supervisor('editor-desk', editorAccess, { port: H.slot.port(0) })])
  .projections([markdown.board('BOARD.md'), markdown.telemetry('TELEMETRY.md')]);
=== END ===

=== FILE: scenarios/07-multi-tenant.ts ===
import { z } from 'zod';
import { H } from 'harness-dsl';
import * as claude from 'harness-dsl/claude-code';
import * as anthropic from 'harness-dsl/anthropic';
import * as sqlite from 'harness-dsl/sqlite';
import * as jsonl from 'harness-dsl/jsonl';
import * as linear from 'harness-dsl/linear';
import * as folder from 'harness-dsl/folder';
import * as git from 'harness-dsl/git';
import * as local from 'harness-dsl/local';
import * as markdown from 'harness-dsl/markdown';

const sharedQuota = '/home/owner/.harness/quota.sqlite';

const subscriptionOne = claude.subscription('claude-max-1', { configDir: H.env('CLAUDE_DIR_1') });
const subscriptionTwo = claude.subscription('claude-max-2', { configDir: H.env('CLAUDE_DIR_2') });
const subscriptionThree = claude.subscription('claude-max-3', { configDir: H.env('CLAUDE_DIR_3') });
const apiAccount = anthropic.account('anthropic-api', { apiKey: H.env('ANTHROPIC_API_KEY') });

const sonnet = claude.model('claude-sonnet-4');
const opus = claude.model('claude-opus-4');

const soonestExpiring = H.policy.account('soonest-expiring', (c) =>
  [...c.eligible].sort((a, b) => a.windowEndsAt - b.windowEndsAt)[0] ?? null,
);

const ranked = H.policy.recall('specific-then-proven', (c) =>
  [...c.candidates]
    .sort((a, b) => b.specificity - a.specificity || b.track.succeeded - a.track.succeeded)
    .slice(0, c.limit),
);

const ownerTaste = H.memory.taste('owner-taste');
const sharedTasteJournal = H.journal('owner-taste', ownerTaste)
  .store(jsonl.memory('/home/owner/.harness/taste.jsonl'))
  .recall(ranked);

const ownerAccess = H.access('owner').allows([
  H.ops.readWork,
  H.ops.createWork,
  H.ops.updateWork,
  H.ops.resolveBlocks,
  H.ops.writeMemory,
  H.ops.readTelemetry,
  H.ops.readAccounts,
  H.ops.setShares,
]);

const Todo = H.state('Todo', 'pending');
const Building = H.state('Building', 'active');
const Done = H.state('Done', 'terminal', 'success');
const Abandoned = H.state('Abandoned', 'terminal', 'failure');

const Bug = H.work('Bug')
  .attributes({ identifier: z.string(), title: z.string() })
  .fields({ description: z.string() })
  .states([Todo, Building, Done, Abandoned])
  .key((unit) => unit.attributes.identifier);

const Feature = H.work('Feature')
  .attributes({ identifier: z.string(), title: z.string() })
  .fields({ description: z.string() })
  .states([Todo, Building, Done, Abandoned])
  .key((unit) => unit.attributes.identifier);

const linearConnection = { apiKey: H.env('LINEAR_API_KEY'), team: 'PRODUCT' };

const codingExperience = H.memory.experience('coding-experience');
const codingExperienceJournal = H.journal('coding-experience', codingExperience)
  .store(jsonl.memory('memory/coding-experience.jsonl'))
  .recall(ranked);

const codingPool = H.pool('coding-pool')
  .accounts([
    { account: subscriptionOne, share: 0.6 },
    { account: subscriptionTwo, share: 0.6 },
    { account: subscriptionThree, share: 0.6 },
  ])
  .prefer(soonestExpiring)
  .fallback(apiAccount);

const builderModel = H.policy.model('builder-model', [sonnet, opus], (c) => {
  const cheap = c.metrics.success({ kind: c.unit?.kind ?? 'Bug', model: sonnet, window: { days: 14 } });
  return cheap.n >= 20 && cheap.rate !== null && cheap.rate < 0.85 ? opus : sonnet;
});

const projectChecks = H.command('project-checks', ['pnpm', 'run', 'check']);

const builderRole = H.role('builder')
  .intents(['read', 'write', 'execute', 'search', 'ask'])
  .instructions('Implement the task. Resolve every listed deficit. Ask the owner when a decision is theirs.')
  .input({ task: z.string(), deficits: z.array(z.string()) })
  .output({ summary: z.string() });

const auditorRole = H.role('auditor')
  .intents(['read', 'search', 'remember'])
  .instructions('List every deficit in the change against the task. An empty list means done.')
  .input({ task: z.string(), summary: z.string() })
  .output({ deficits: z.array(z.string()) });

const builder = H.agent('builder', builderRole)
  .model(builderModel)
  .pool(codingPool)
  .recalls([codingExperienceJournal, sharedTasteJournal])
  .leaseWrites()
  .mustPass(projectChecks);

const auditor = H.agent('auditor', auditorRole)
  .model(opus)
  .pool(codingPool)
  .recalls([codingExperienceJournal])
  .records(codingExperienceJournal);

const ticketFlow = H.flow('ticket')
  .requires({ title: z.string(), description: z.string() })
  .params({ rounds: z.number() })
  .mark('building')
  .loop(
    'rounds',
    { carry: { deficits: z.array(z.string()) }, rounds: (c) => c.params.rounds },
    (round) =>
      round
        .step('build', builder, (c) => ({
          task: `${c.input.title}\n\n${c.input.description}`,
          deficits: c.carry?.deficits ?? [],
        }))
        .step('audit', auditor, (c) => ({ task: c.input.title, summary: c.out.build.summary })),
    (last) => (last.audit.deficits.length > 0 ? { deficits: last.audit.deficits } : null),
  )
  .ends(['done', 'abandoned'], (c) => (c.out.rounds.exhausted ? 'abandoned' : 'done'));

const ticketStates = { building: Building, done: Done, abandoned: Abandoned, failed: Abandoned };
const worktrees = git.worktree({ repo: '.', base: 'main', slots: 3 });
const linearStatus = { Todo: 'Todo', Building: 'In Progress', Done: 'Done', Abandoned: 'Canceled' };

const bugs = H.lane('bugs', Bug)
  .supply([
    linear.issues(Bug, { ...linearConnection, labels: ['bug'] }, (issue) => ({
      attributes: { identifier: issue.identifier, title: issue.title },
      fields: { description: issue.description },
    })),
    folder.files(Bug, 'inbox/bugs', (file) => ({
      attributes: { identifier: file.path, title: file.body.split('\n')[0] ?? file.path },
      fields: { description: file.body },
    })),
    H.supply.operator(),
  ])
  .store(linear.store(Bug, { ...linearConnection, status: linearStatus }))
  .handler(ticketFlow, { states: ticketStates, params: { rounds: 3 } })
  .runner(worktrees)
  .wip(2);

const features = H.lane('features', Feature)
  .supply([
    linear.issues(Feature, { ...linearConnection, labels: ['feature'] }, (issue) => ({
      attributes: { identifier: issue.identifier, title: issue.title },
      fields: { description: issue.description },
    })),
    H.supply.operator(),
  ])
  .store(linear.store(Feature, { ...linearConnection, status: linearStatus }))
  .handler(ticketFlow, { states: ticketStates, params: { rounds: 5 } })
  .runner(worktrees);

export const codingHarness = H.harness('coding-team')
  .ledger(sqlite.ledger('coding-ledger.sqlite', { quotaPath: sharedQuota }))
  .lanes([bugs, features])
  .schedule(H.policy.schedule('bugs-then-features', (c) => ({
    start: [...c.candidates].sort((a, b) => {
      const rank = (x: typeof a) => (x.is(bugs) ? 0 : x.waitedMs > 86_400_000 ? 0 : 1);
      return rank(a) - rank(b) || b.waitedMs - a.waitedMs;
    }),
  })))
  .clients([claude.supervisor('coding-supervisor', ownerAccess, { port: H.slot.port(0) })])
  .projections([markdown.board('coding/BOARD.md'), markdown.telemetry('coding/TELEMETRY.md')]);

const Found = H.state('Found', 'pending');
const Writing = H.state('Writing', 'active');
const Published = H.state('Published', 'terminal', 'success');
const BrokenLinks = H.state('BrokenLinks', 'terminal', 'failure');
const WriteFailed = H.state('WriteFailed', 'terminal', 'failure');

const DocPage = H.work('DocPage')
  .attributes({ path: z.string(), title: z.string() })
  .fields({ body: z.string() })
  .states([Found, Writing, Published, BrokenLinks, WriteFailed])
  .key((unit) => unit.attributes.path);

const docsExperience = H.memory.experience('docs-experience');
const docsExperienceJournal = H.journal('docs-experience', docsExperience)
  .store(jsonl.memory('memory/docs-experience.jsonl'))
  .recall(ranked);

const docsPool = H.pool('docs-pool')
  .accounts([
    { account: subscriptionOne, share: 0.3 },
    { account: subscriptionTwo, share: 0.3 },
    { account: subscriptionThree, share: 0.3 },
  ])
  .prefer(soonestExpiring);

const writerRole = H.role('writer')
  .intents(['read', 'write', 'remember'])
  .instructions('Rewrite the page so it is accurate, complete and in the owner style.')
  .input({ path: z.string(), title: z.string(), body: z.string() })
  .output({ body: z.string() });

const writer = H.agent('writer', writerRole)
  .model(sonnet)
  .pool(docsPool)
  .recalls([docsExperienceJournal, sharedTasteJournal])
  .records(docsExperienceJournal);

const linkCheck = H.command('link-check', ['npx', 'linkinator']);

const docFlow = H.flow('doc-page')
  .requires({ path: z.string(), title: z.string(), body: z.string() })
  .mark('writing')
  .step('write', writer, (c) => ({ path: c.input.path, title: c.input.title, body: c.input.body }))
  .step('links', linkCheck, (c) => ({ args: [c.input.path] }), { onRestart: 'rerun' })
  .ends(['published', 'broken'], (c) => (c.out.links.exitCode === 0 ? 'published' : 'broken'));

const docPages = H.lane('doc-pages', DocPage)
  .supply([
    folder.files(DocPage, 'docs', (file) => {
      const title = file.frontmatter['title'];
      return {
        attributes: { path: file.path, title: typeof title === 'string' ? title : file.path },
        fields: { body: file.body },
      };
    }),
  ])
  .store(folder.frontmatter(DocPage, 'docs'))
  .handler(docFlow, {
    states: { writing: Writing, published: Published, broken: BrokenLinks, failed: WriteFailed },
  })
  .runner(local.shell({ slots: 2, cwd: '.' }))
  .wip(2);

export const docsHarness = H.harness('documentation')
  .ledger(sqlite.ledger('docs-ledger.sqlite', { quotaPath: sharedQuota }))
  .lanes([docPages])
  .schedule(H.policy.schedule('oldest-first', (c) => ({
    start: [...c.candidates].sort((a, b) => b.waitedMs - a.waitedMs),
  })))
  .clients([claude.supervisor('docs-supervisor', ownerAccess, { port: H.slot.port(1) })])
  .projections([markdown.board('docs/BOARD.md'), markdown.telemetry('docs/TELEMETRY.md')]);
=== END ===

=== FILE: scenarios/08-hostile-lifecycles.ts ===
import { z } from 'zod';
import { H } from 'harness-dsl';
import * as anthropic from 'harness-dsl/anthropic';
import * as claude from 'harness-dsl/claude-code';
import * as sqlite from 'harness-dsl/sqlite';
import * as http from 'harness-dsl/http';
import * as local from 'harness-dsl/local';
import * as markdown from 'harness-dsl/markdown';

const apiAccount = anthropic.account('anthropic-api', { apiKey: H.env('ANTHROPIC_API_KEY') });
const strong = anthropic.model('claude-opus-4');
const cheap = anthropic.model('claude-sonnet-4');
const runner = local.shell({ slots: 4 });
const ledger = sqlite.ledger('lifecycles-ledger.sqlite');

const ExperimentQueued = H.state('ExperimentQueued', 'pending');
const Measuring = H.state('Measuring', 'active');
const AWins = H.state('AWins', 'terminal', 'success');
const BWins = H.state('BWins', 'terminal', 'success');
const Inconclusive = H.state('Inconclusive', 'terminal', 'neutral');
const ExperimentBroken = H.state('ExperimentBroken', 'terminal', 'failure');

const Experiment = H.work('Experiment')
  .attributes({ experimentId: z.string(), hypothesis: z.string() })
  .states([ExperimentQueued, Measuring, AWins, BWins, Inconclusive, ExperimentBroken])
  .key((unit) => unit.attributes.experimentId);

const measure = H.command('measure-experiment', ['node', 'scripts/measure.js']);
const decideWinner = H.command('decide-winner', ['node', 'scripts/decide.js']).parses({
  winner: z.enum(['a', 'b', 'none']),
});

const experimentFlow = H.flow('experiment')
  .requires({ experimentId: z.string() })
  .mark('measuring')
  .loop(
    'hours',
    { carry: { lastExit: z.number() }, rounds: () => 24 * 14 },
    (round) =>
      round
        .step('measure', measure, (c) => ({ args: [c.input.experimentId, String(c.round)] }), { onRestart: 'rerun' })
        .wait('nextHour', H.time.after({ hours: 1 })),
    (last) => ({ lastExit: last.measure.exitCode }),
  )
  .step('decide', decideWinner, (c) => ({ args: [c.input.experimentId] }), { onRestart: 'rerun' })
  .ends(['aWins', 'bWins', 'inconclusive'], (c) =>
    c.out.decide.data.winner === 'a' ? 'aWins' : c.out.decide.data.winner === 'b' ? 'bWins' : 'inconclusive',
  );

const experiments = H.lane('experiments', Experiment)
  .supply([H.supply.operator()])
  .store(sqlite.store(Experiment, 'lifecycles-store.sqlite'))
  .handler(experimentFlow, {
    states: {
      measuring: Measuring,
      aWins: AWins,
      bWins: BWins,
      inconclusive: Inconclusive,
      failed: ExperimentBroken,
    },
  })
  .runner(runner)
  .wip(3);

const DueReview = H.state('DueReview', 'pending');
const Reviewing = H.state('Reviewing', 'active');
const Customer = H.state('Customer', 'waiting');
const Suspended = H.state('Suspended', 'waiting');
const Churned = H.state('Churned', 'terminal', 'neutral');

const Tenancy = H.work('Tenancy')
  .attributes({ customerId: z.string(), plan: z.string() })
  .states([DueReview, Reviewing, Customer, Suspended, Churned])
  .signals({ churned: { reason: z.string() }, reinstated: { note: z.string() } })
  .timers(() => ({ monthlyReview: H.time.monthly(1, '09:00', 'Europe/Berlin') }))
  .key((unit) => unit.attributes.customerId);

const usageReport = H.command('usage-report', ['node', 'scripts/usage.js']).parses({
  seats: z.number(),
  usageUsd: z.number(),
});

const accountAnalyst = H.role('account-analyst')
  .intents(['read'])
  .instructions('Summarise the month for the account owner: usage trend, risk, upsell signal.')
  .input({ customerId: z.string(), plan: z.string(), seats: z.number(), usageUsd: z.number() })
  .output({ summary: z.string() });

const analyst = H.agent('account-analyst', accountAnalyst).model(cheap).pool(apiAccount);

const tenancyReview = H.flow('tenancy-review')
  .requires({ customerId: z.string(), plan: z.string() })
  .mark('reviewing')
  .step('usage', usageReport, (c) => ({ args: [c.input.customerId] }), { onRestart: 'rerun' })
  .step('summary', analyst, (c) => ({
    customerId: c.input.customerId,
    plan: c.input.plan,
    seats: c.out.usage.data.seats,
    usageUsd: c.out.usage.data.usageUsd,
  }))
  .halt('decision', {
    ask: (c) => c.out.summary.summary,
    decision: { action: z.enum(['upsell', 'keep', 'suspend']), note: z.string() },
  })
  .ends(['customer', 'suspended'], (c) => (c.out.decision.action === 'suspend' ? 'suspended' : 'customer'));

const customerEvent = z.object({
  customerId: z.string(),
  type: z.enum(['signedUp', 'churned']),
  plan: z.string(),
  reason: z.string(),
});

const tenancies = H.lane('tenancies', Tenancy)
  .supply([
    H.supply.operator(),
    http.webhook(Tenancy, { path: '/crm', port: H.slot.port(1), secret: H.env('CRM_SECRET') }, (body) => {
      const parsed = customerEvent.safeParse(body);
      if (!parsed.success) return null;
      if (parsed.data.type === 'signedUp') {
        return { create: { attributes: { customerId: parsed.data.customerId, plan: parsed.data.plan } } };
      }
      return { key: parsed.data.customerId, signal: 'churned', payload: { reason: parsed.data.reason } };
    }),
  ])
  .store(sqlite.store(Tenancy, 'lifecycles-store.sqlite'))
  .handler(tenancyReview, {
    states: { reviewing: Reviewing, customer: Customer, suspended: Suspended, failed: Customer },
  })
  .runner(runner);

