  const urgency = (x: (typeof c.candidates)[number]) =>
    x.is(escalations) || x.is(audits) ? Number.NEGATIVE_INFINITY : (x.timers['sla'] ?? Number.POSITIVE_INFINITY) - c.clock.now;
