  H.ops.updateWork,
  H.ops.resolveBlocks,
  H.ops.readMemory,
  H.ops.writeMemory,
  H.ops.curateMemory,
  H.ops.readTelemetry,
]);

export const supportHarness = H.harness('support')
  .ledger(sqlite.ledger('support-ledger.sqlite'))
  .lanes([conversations, escalations, audits])
  .triggers([
