  ])
  .schedule(supportSchedule)
  .clients([claude.supervisor('support-supervisor', reviewerAccess, { port: H.slot.port(0) })])
  .projections([markdown.board('BOARD.md'), markdown.telemetry('TELEMETRY.md')]);
