  .schedule(H.policy.schedule('releases-then-smoke', (c) => ({
    start: [...c.candidates].sort((a, b) => (a.is(smokes) ? 0 : 1) - (b.is(smokes) ? 0 : 1)),
  })))
  .clients([claude.supervisor('release-supervisor', releaseManagerAccess, { port: H.slot.port(0) })])
