const approvalBounds = { windowDays: 7, trip: { below: 0.9 }, reset: { above: 0.95 }, minSamples: 50 };
const errorBounds = { windowHours: 1, trip: { above: 0.2 }, reset: { below: 0.05 }, minSamples: 20 };

